-- +goose Up
-- CR-031 (D-131): the Riverside map buildings 6–13 and 18 become real buildings with floors, plans, rooms
-- and a 3D shape key, linked to their site blocks. Rooms traced from attachments/building plan/6-… to 13-…,
-- 18-…; x along the long side from the left of the plan sheet, z from its top edge, metres. Office / tenant
-- rooms add up to each sheet's totals; where a sheet has no common-area outline the common area has no
-- shape (a point outside every room then belongs to none). Riverside 1 and 2 have 2 floors (the third plan page is the shared toilet block).
-- Warehouse 3 uses its plan size 80 × 40 m and moves 22 m further along its long side so it does not
-- overlap Warehouse 2 / โรงเรือน (owner 2026-10-30). Unnamed rooms named by Claude.

-- Stops here when a building with one of these names already exists: rename it in settings first.
ON CONFLICT (id) DO UPDATE SET model_key = EXCLUDED.model_key; -- kept by a Down while in use

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT (id) DO UPDATE SET plan_shape = EXCLUDED.plan_shape, updated_at = now();

UPDATE platform.site_blocks s SET building_id = v.building_id::uuid, x_m = v.x, z_m = v.z, width_m = v.w, depth_m = v.d,
    storeys = v.n, updated_at = now()
FROM (VALUES
    (6, 'c031b1d0-0000-4000-8000-000000000006', -122.2, 124.6, 32.0, 20.0, 1),
    (7, 'c031b1d0-0000-4000-8000-000000000007', -188.9, 147.0, 24.0, 8.5, 2),
    (8, 'c031b1d0-0000-4000-8000-000000000008', -162.0, 111.9, 26.0, 12.6, 2),
    (9, 'c031b1d0-0000-4000-8000-000000000009', -136.4, 98.1, 15.0, 10.0, 2),
    (10, 'c031b1d0-0000-4000-8000-000000000010', -258.5, 202.1, 48.0, 17.7, 2),
    (11, 'c031b1d0-0000-4000-8000-000000000011', -200.0, 90.8, 68.5, 15.0, 1),
    (12, 'c031b1d0-0000-4000-8000-000000000012', -287.9, 181.1, 40.0, 15.0, 1),
    (13, 'c031b1d0-0000-4000-8000-000000000013', -317.1, 235.7, 80.0, 40.0, 1),
    (18, 'c031b1d0-0000-4000-8000-000000000018', -276.1, 230.7, 36.1, 16.5, 1)
) AS v (map_no, building_id, x, z, w, d, n)
WHERE s.map_no = v.map_no;

-- +goose Down
-- A building goes only when no ticket or asset uses it; otherwise it stays (without its 3D key).
UPDATE platform.site_blocks s SET building_id = NULL, x_m = v.x, z_m = v.z, width_m = v.w, depth_m = v.d, storeys = v.n, updated_at = now()
FROM (VALUES (6, -122.2, 124.6, 32.0, 20.0, 1), (7, -188.9, 147.0, 24.0, 15.0, 3), (8, -162.0, 111.9, 26.0, 14.6, 3),
    (9, -136.4, 98.1, 15.0, 10.0, 2), (10, -258.5, 202.1, 57.0, 17.7, 2), (11, -200.0, 90.8, 68.5, 15.0, 1),
    (12, -287.9, 181.1, 40.0, 15.0, 1), (13, -298.9, 200.6, 18.0, 17.3, 1), (18, -276.1, 230.7, 36.1, 16.5, 1)) AS v (map_no, x, z, w, d, n)
WHERE s.map_no = v.map_no;
CREATE TEMP TABLE cr031_free ON COMMIT DROP AS
SELECT b.id FROM platform.buildings b
WHERE b.id::text LIKE 'c031b1d0-%'
    AND NOT EXISTS (SELECT 1 FROM repair.tickets t WHERE t.building_id = b.id)
    AND NOT EXISTS (SELECT 1 FROM platform.assets a JOIN platform.rooms ar ON ar.id = a.room_id
                    JOIN platform.floors af ON af.id = ar.floor_id WHERE af.building_id = b.id);
DELETE FROM platform.rooms r USING platform.floors f
WHERE r.floor_id = f.id AND f.building_id IN (SELECT id FROM cr031_free);
DELETE FROM platform.floor_plans fp USING platform.floors f
WHERE fp.floor_id = f.id AND f.building_id IN (SELECT id FROM cr031_free);
DELETE FROM platform.floors f WHERE f.building_id IN (SELECT id FROM cr031_free);
DELETE FROM platform.buildings b WHERE b.id IN (SELECT id FROM cr031_free);
UPDATE platform.buildings SET model_key = NULL WHERE id::text LIKE 'c031b1d0-%';
